  .content { max-width:900px; margin:0 auto; padding:0 2rem 4rem; }

  /* Sections */
  .section-divider { display:flex; align-items:center; gap:1rem; margin:3rem 0 1.5rem; color:var(--text-muted); font-size:0.75rem; font-weight:700; text-transform:uppercase; letter-spacing:0.1em; }
  .section-divider::before, .section-divider::after { content:''; flex:1; height:1px; background:#e2e8f0; }

  /* Cards */
  .phase-card { background:white; border:1px solid #e2e8f0; border-radius:16px; padding:1.75rem; margin-bottom:1.25rem; position:relative; overflow:hidden; }
  .phase-card::before { content:''; position:absolute; top:0; left:0; right:0; height:3px; }
  .phase-card h3 { font-size:1.1rem; font-weight:800; margin-bottom:0.75rem; display:flex; align-items:center; gap:0.5rem; }
  .phase-card p, .phase-card li { font-size:0.9rem; color:var(--text-secondary); line-height:1.7; }
  .phase-card ul, .phase-card ol { padding-left:1.25rem; margin:0.75rem 0; }
  .phase-card li { margin-bottom:0.4rem; }

  .phase-1::before { background:linear-gradient(90deg,var(--accent),#818cf8); }
  .phase-2::before { background:linear-gradient(90deg,var(--blue),#60a5fa); }
  .phase-3::before { background:linear-gradient(90deg,var(--red),#f87171); }
  .phase-4::before { background:linear-gradient(90deg,var(--green),#34d399); }
  .phase-5::before { background:linear-gradient(90deg,var(--amber),#fbbf24); }

  /* Phase number */
  .phase-num { width:32px; height:32px; border-radius:8px; display:inline-flex; align-items:center; justify-content:center; color:white; font-weight:900; font-size:0.85rem; flex-shrink:0; }

